class Bitset:
    def __init__(self, size):
        self.s = ['0'] * size
        self.c = 0
    def fix(self, idx):
        if self.s[idx] == '0':
            self.s[idx] = '1'
            self.c += 1
    def unfix(self, idx):
        if self.s[idx] == '1':
            self.s[idx] = '0'
            self.c -= 1
    def flip(self):
        self.s = ['1' if x == '0' else '0' for x in self.s]
        self.c = len(self.s) - self.c
    def all(self):
        return self.c == len(self.s)
    def one(self):
        return self.c > 0
    def count(self):
        return self.c
    def toString(self):
        return ''.join(self.s)

