    private int c, n;
    private boolean on(int i) { return (b[i] == '1') != f; }
    public Bitset(int size) { b = new char[size]; java.util.Arrays.fill(b, '0'); n = size; }
    public void fix(int idx) { if (!on(idx)) { c++; b[idx] = f ? '0' : '1'; } }
    public void unfix(int idx) { if (on(idx)) { c--; b[idx] = f ? '1' : '0'; } }
    public void flip() { f = !f; c = n - c; }
    public boolean all() { return c == n; }
    public boolean one() { return c > 0; }
    public int count() { return c; }
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (char ch : b) sb.append(f ? (ch == '0' ? '1' : '0') : ch);
        return sb.toString();
    }
}

